297: /* choices is null terminated. Return the
298:    index of the choosen item, or -1 if escape was
299:    pressed.*/
300: int select_mode(char *header, char *choices[])
301: {
302:   int i,key,choice = 0;
303:   while (1)
304:     {
305:       console_clear();
306:       console_write(header);
307:       console_write("\n");
308:       for (i=0;choices[i];i++)
309: 	{
310: 	  if (choice == i)
311: 	    console_write("*");
312: 	  else
313: 	    console_write(" ");
314: 	  console_write(choices[i]);
315: 	  console_write("\n");
316: 	}
317:       console_frame();
318:       key = wait_for_key();
319:       switch (key)
320: 	{
321: 	case SDLK_UP:
322: 	  choice--;
323: 	  if (choice < 0)
324: 	    { 
325: 	      /* seek last item */
326: 	      choice = 0;
327: 	      while (choices[choice + 1] != 0)
328: 		choice++;
329: 	    }
330: 	  break;
331: 	case SDLK_DOWN:
332: 	  choice++;
333: 	  if (choices[choice] == 0)
334: 	    choice = 0;
335: 	  break;
336: 	case SDLK_ESCAPE:
337: 	  return -1;
338: 	default:
339: 	  return choice;
340: 	}
341:     }
342: }
